function projectEffort(p){return p.projects.reduce((n,x)=>n+(x.paused?0:x.effort),0)+(p.study?.effort||0)+(p.passions?Object.values(p.passions).reduce((n,x)=>n+([0,0,1,2][x.intensity]||0),0):0)}
